WITH valid AS (SELECT *, ROUND(cost * 1.07, 2) AS cost_scaled, LEAST(cost, price) AS least_cost_price, COALESCE(brand, 'UNKNOWN') AS brand_filled FROM products WHERE launch_date > DATE '2023-12-17' AND brand IS NOT NULL AND launch_date BETWEEN '2024-03-01' AND '2025-02-01') SELECT CASE WHEN stock_qty >= 382 THEN 'PREMIUM' ELSE 'STANDARD' END AS stock_qty_tier, DATE_TRUNC('WEEK', launch_date) AS week_start, supplier_id, MAX(stock_qty) FILTER (WHERE category = 'Fashion') AS fashion_max_stock_qty, MAX(price) FILTER (WHERE category = 'Books') AS books_max_price, SUM(CASE WHEN brand = 'Acme' THEN cost ELSE 0 END) AS acme_cost, ROUND(AVG(least_cost_price), 2) AS avg_least_cost_price, GROUPING(CASE WHEN stock_qty >= 382 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM valid GROUP BY ROLLUP (CASE WHEN stock_qty >= 382 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', launch_date), supplier_id) HAVING MAX(stock_qty) FILTER (WHERE category = 'Fashion') > 0 ORDER BY acme_cost DESC;
